INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',364,'{"_type":"chat:Message","id":"8641420749:891","threadId":"telegram:8641420749","text":"Pas étiré hier, un peu fatigué ce matin. Je vais sortir pedaler la. Anything to do beforehand?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Pas étiré hier, un peu fatigué ce matin. Je vais sortir pedaler la. Anything to do beforehand?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":95,"offset":94}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":95,"offset":94}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":95,"offset":94}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T08:56:59.000Z","edited":false},"attachments":[],"isMention":false}',1786006661116);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',365,'{"_type":"chat:Message","id":"8641420749:626","threadId":"telegram:8641420749","text":"N’utilise jamais de sigle nouveau sans les avoir définis. Pareil pour les termes techniques. Garde ca en memoire. Je ne suis pas un expert en finance. \nDonc ici tu dois expliquer :\nDCA, tilt factoriel, equal-weight, caps, PPR, PV,","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"N’utilise jamais de sigle nouveau sans les avoir définis. Pareil pour les termes techniques. Garde ca en memoire. Je ne suis pas un expert en finance.\nDonc ici tu dois expliquer :\nDCA, tilt factoriel, equal-weight, caps, PPR, PV,","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":50,"offset":230}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":50,"offset":230}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":50,"offset":230}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T08:58:32.000Z","edited":false},"attachments":[],"isMention":false}',1786006712273);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',366,'{"_type":"chat:Message","id":"8641420749:629","threadId":"telegram:8641420749","text":"Oui","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Oui","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":4,"offset":3}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":4,"offset":3}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":4,"offset":3}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T09:05:27.000Z","edited":false},"attachments":[],"isMention":false}',1786007124761);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',367,'{"_type":"chat:Message","id":"8641420749:631","threadId":"telegram:8641420749","text":"Un autre point à prendre en compte, mon beau frere est architecte et il à acheté plusieurs T1 pu T2 a Madrid pour faire un renovation a bas coup mais style tres en vogue. Donc tres alléchant pour un locataire entre l’avant vieil appart’ classique du centre de Madrid et l’apres, tres modernisé. Peut etre un levier a utiliser pour l’achat de notre T1 ici. A approfondir, si ca vaut le coup et comment utiliser cela. Sachant qu’on payerait donc peu de frais d’architecte avec mon beau frere. D’ailleurs j’ai choisi T1 car on m’a dit que c’est le plus facile a louer, et dans l’idee de rester sous les 2300€. Mais aussi a valider ce point. \n\nJe pars faire du velo pendant 1h45. Qu’est ce que tu peux faire pendant ce temps ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Un autre point à prendre en compte, mon beau frere est architecte et il à acheté plusieurs T1 pu T2 a Madrid pour faire un renovation a bas coup mais style tres en vogue. Donc tres alléchant pour un locataire entre l’avant vieil appart’ classique du centre de Madrid et l’apres, tres modernisé. Peut etre un levier a utiliser pour l’achat de notre T1 ici. A approfondir, si ca vaut le coup et comment utiliser cela. Sachant qu’on payerait donc peu de frais d’architecte avec mon beau frere. D’ailleurs j’ai choisi T1 car on m’a dit que c’est le plus facile a louer, et dans l’idee de rester sous les 2300€. Mais aussi a valider ce point.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":638,"offset":637}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":639,"offset":638}}},{"type":"paragraph","children":[{"type":"text","value":"Je pars faire du velo pendant 1h45. Qu’est ce que tu peux faire pendant ce temps ?","position":{"start":{"line":3,"column":1,"offset":640},"end":{"line":3,"column":83,"offset":722}}}],"position":{"start":{"line":3,"column":1,"offset":640},"end":{"line":3,"column":83,"offset":722}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":83,"offset":722}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T09:09:18.000Z","edited":false},"attachments":[],"isMention":false}',1786007356898);
