INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',369,'{"_type":"chat:Message","id":"8641420749:898","threadId":"telegram:8641420749","text":"Donne moi le plan exact pour toute la periode de l’Espagne, je fais ma valise, je veux prevoir la nutrition et le matos.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Donne moi le plan exact pour toute la periode de l’Espagne, je fais ma valise, je veux prevoir la nutrition et le matos.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":121,"offset":120}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":121,"offset":120}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":121,"offset":120}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T20:25:43.000Z","edited":false},"attachments":[],"isMention":false}',1786047942387);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',370,'{"_type":"chat:Message","id":"8641420749:901","threadId":"telegram:8641420749","text":"Explique moi le rationnel pour le ratio velo/run. Et explique moi comment ce plan est mieux que le plan de la semaine suivante l’annee derniere ? Depart Marseille Napoli une semaine plus tard l’annee derniere","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Explique moi le rationnel pour le ratio velo/run. Et explique moi comment ce plan est mieux que le plan de la semaine suivante l’annee derniere ? Depart Marseille Napoli une semaine plus tard l’annee derniere","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":209,"offset":208}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":209,"offset":208}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":209,"offset":208}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T20:37:00.000Z","edited":false},"attachments":[],"isMention":false}',1786048619241);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',371,'{"_type":"chat:Message","id":"8641420749:904","threadId":"telegram:8641420749","text":"Je veux une comparaison plus specifique de la semaine prochaine avec la semaine suivante de l’annee derniere, va la voir dans l’historique trainingpeaks que je t’avais envoyé ou sur strava. Et compare la valeur complète de chaque semaine, je veux une analyse quantitative. Soit ouvert, peut etre qu’on peut en apprendre qqch pour améliorer le plan de la semaine prochaine","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je veux une comparaison plus specifique de la semaine prochaine avec la semaine suivante de l’annee derniere, va la voir dans l’historique trainingpeaks que je t’avais envoyé ou sur strava. Et compare la valeur complète de chaque semaine, je veux une analyse quantitative. Soit ouvert, peut etre qu’on peut en apprendre qqch pour améliorer le plan de la semaine prochaine","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":372,"offset":371}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":372,"offset":371}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":372,"offset":371}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T20:44:26.000Z","edited":false},"attachments":[],"isMention":false}',1786049066129);
