INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',460,'{"_type":"chat:Message","id":"8641420749:153","threadId":"telegram:8641420749","text":"When are we flying to Geneva in August?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"When are we flying to Geneva in August?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":40,"offset":39}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":40,"offset":39}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":40,"offset":39}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-08-05T16:30:17.000Z","edited":false},"attachments":[],"isMention":false}',1786552217387);
